ST.xhtml:
{region "§1 Gate securite"}
// 🛑 1. GATE — bus coupé / Enable=FALSE : tout neutralisé, sorties sûres
IF NOT Enable OR NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational THEN
    Ready := FALSE;
    DeadmanButton := FALSE; DeadmanArmed := FALSE; DeadmanArmPending := FALSE;
    AtNeutral := TRUE;
    AxisCmdX.Enable := FALSE; AxisCmdX.StartStop := FALSE; AxisCmdX.SpeedRef := 0.0;
    AxisCmdX.DirectionNegative := FALSE; AxisCmdX.DirectionPositive := FALSE; AxisCmdX.AtNeutral := TRUE;
    AxisCmdY.Enable := FALSE; AxisCmdY.StartStop := FALSE; AxisCmdY.SpeedRef := 0.0;
    AxisCmdY.DirectionNegative := FALSE; AxisCmdY.DirectionPositive := FALSE; AxisCmdY.AtNeutral := TRUE;
    NeutralHoldTimer(IN := FALSE, PT := NeutralHoldTime);
    DeadmanArmTimer(IN := FALSE, PT := DeadmanArmHoldTime);
    DeadmanArmGraceTimer(IN := FALSE, PT := DeadmanArmGraceTime);
    ErrorIdCause := ErrorIdCause OR 16#0004;   // perte bus visible (le socle gere l'acquittement)
    RETURN;
END_IF;
Ready := TRUE;
{endregion}

{region "§2 Reset"}
// 🔑 2. RESET DÉFAUT (front + cause disparue)
ResetEdge(CLK := Reset);
IF ResetEdge.Q AND (RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000) THEN
    ErrorIdCause := ErrorIdCause AND (NOT 16#0001);   // efface bit0 (calibration)
END_IF;
// Bus revenu → nettoie bit2 (perte bus auto-efface)
IF BusCanOpenOP.Operational AND JoystickOP.Operational THEN
    ErrorIdCause := ErrorIdCause AND (NOT 16#0004);
END_IF;
{endregion}

{region "§3 Calibration et mise a echelle"}
// 🎯 4. CALIBRATION (Zone RETAIN)
IF BtnCalibrate AND NOT LastCalibrate THEN
    IF RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000 THEN
        NeutralXMem := RawX;
        NeutralYMem := RawY;
    ELSE
        ErrorIdCause := ErrorIdCause OR 16#0001;   // bit0 : echec calibration
    END_IF;
END_IF;
LastCalibrate := BtnCalibrate;

// 🧮 MISE À L'ÉCHELLE (deadband)
ScaleX(RawIn := RawX, Neutral := NeutralXMem, DeadbandRaw := DeadbandRaw);
ScaleY(RawIn := RawY, Neutral := NeutralYMem, DeadbandRaw := DeadbandRaw);
AtNeutral := (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0);
AxisCmdX.AtNeutral := AtNeutral;
AxisCmdY.AtNeutral := AtNeutral;

// 🛡️ SURVEILLANCE CAPTEUR CONTINUE (AF08 §5bis)
RawOutOfRange := (RawX < (0 - RawOutOfRangeMargin))
              OR (RawX > (10000 + RawOutOfRangeMargin))
              OR (RawY < (0 - RawOutOfRangeMargin))
              OR (RawY > (10000 + RawOutOfRangeMargin));
IF RawOutOfRange THEN
    ErrorIdCause := ErrorIdCause OR 16#0002;    // bit1 : capteur hors plage
ELSE
    ErrorIdCause := ErrorIdCause AND (NOT 16#0002);
END_IF;
{endregion}

{region "§4 Arming homme-mort"}
DeadmanEdge(CLK := RawButton);
IF DeadmanEdge.Q THEN DeadmanArmPending := TRUE; END_IF;
IF NOT RawButton THEN DeadmanArmPending := FALSE; END_IF;

// SÉCURITÉ (AC1) : armement uniquement si ArmingPermit accordé
DeadmanArmTimer(IN := DeadmanArmPending AND NOT DeadmanArmed AND ArmingPermit,
                PT := DeadmanArmHoldTime);
IF DeadmanArmTimer.Q THEN
    DeadmanArmed := TRUE;
    DeadmanArmPending := FALSE;
END_IF;

// WARNING "armement non permis" (AC2)
ArmingPermitDenied := RawButton AND NOT ArmingPermit;

// Désarmement par neutre prolongé (après grâce)
DeadmanArmGraceTimer(IN := DeadmanArmed, PT := DeadmanArmGraceTime);
NeutralHoldTimer(IN := DeadmanArmed AND AtNeutral AND DeadmanArmGraceTimer.Q,
                 PT := NeutralHoldTime);
IF NeutralHoldTimer.Q THEN DeadmanArmed := FALSE; END_IF;
{endregion}

{region "§6 Pipeline axe X"}
CmdXVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleX.OutPct);
AxisCmdX.Enable := NOT RawOutOfRange AND ArmingPermit;
AxisCmdX.SpeedRef := CmdXVal;
AxisCmdX.StartStop := (ABS(CmdXVal) > 0.1);
IF CmdXVal > 0.1 THEN
    AxisCmdX.DirectionNegative := FALSE; AxisCmdX.DirectionPositive := TRUE;
ELSIF CmdXVal < -0.1 THEN
    AxisCmdX.DirectionNegative := TRUE; AxisCmdX.DirectionPositive := FALSE;
ELSE
    AxisCmdX.DirectionNegative := FALSE; AxisCmdX.DirectionPositive := FALSE;
END_IF;
{endregion}

{region "§7 Pipeline axe Y"}
CmdYVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleY.OutPct);
AxisCmdY.Enable := NOT RawOutOfRange AND ArmingPermit;
AxisCmdY.SpeedRef := CmdYVal;
AxisCmdY.StartStop := (ABS(CmdYVal) > 0.1);
IF CmdYVal > 0.1 THEN
    AxisCmdY.DirectionNegative := FALSE; AxisCmdY.DirectionPositive := TRUE;
ELSIF CmdYVal < -0.1 THEN
    AxisCmdY.DirectionNegative := TRUE; AxisCmdY.DirectionPositive := FALSE;
ELSE
    AxisCmdY.DirectionNegative := FALSE; AxisCmdY.DirectionPositive := FALSE;
END_IF;
{endregion}

{region "§8 Statut socle"}
// 🧩 SOCLE DE STATUT STANDARD — remplit Status
WarningMask := 0;   // tous les bits restent en ErrorId (comportement joystick inchangé)
ErrorIdCause := ErrorIdCause;
JoystickErrorTexts[0] := 'Echec calibration joystick (RawX/Y hors zone)';
JoystickErrorTexts[1] := 'Capteur joystick hors plage ADC';
JoystickErrorTexts[2] := 'Perte liaison bus CAN joystick';
JoystickWarningTexts[1] := 'Capteur joystick hors plage ADC (warning)';
JoystickWarningTexts[2] := 'Perte liaison bus CAN joystick (warning)';

instFbStatus(Enable := Enable, Reset := Reset,
             ErrorIdCause := ErrorIdCause, WarningMask := WarningMask,
             ErrorTexts := JoystickErrorTexts, WarningTexts := JoystickWarningTexts);
Status := instFbStatus.Status;
Ready := NOT Status.Error;
Status.Busy := FALSE; Status.Done := FALSE;
{endregion}

IF RawIn >= Neutral THEN
    Delta := INT_TO_REAL(10000 - Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
ELSE
    Delta := INT_TO_REAL(Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
END_IF;

IF ABS(RawIn - Neutral) <= DeadbandRaw THEN
    OutPct := 0.0;
END_IF;

// 🛡️ Limitation de plage : une valeur brute hors plage nominale ne doit jamais
// produire une consigne supérieure à ±100 %. Ce garde-fou protège les
// consommateurs en aval, notamment la translation M3.
OutPct := LIMIT(-100.0, OutPct, 100.0);

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — Enable = FALSE → statut neutre/sûr
Ready := Enable;
IF NOT Enable THEN
    Status.Busy := FALSE; Status.Done := FALSE;
    Status.Error := FALSE; Status.ErrorId := 0;
    Status.Warning := FALSE; Status.WarningId := 0;
    Status.State := E_State.DISABLED; Status.StateAtError := E_State.DISABLED;
    Status.ResetRequested := FALSE;
    Status.WarningIdTxt := ''; Status.ErrorIdTxt := '';
    ErrorIdLatched := 0; FaultCause := 0; WarningCause := 0;
    RETURN;
END_IF;
Status.State := E_State.READY;
{endregion}

{region "§2 Classification des causes (exclusivité)"}
// 2. Un bit est exclusivement warning OU fault (jamais les deux, §3bis)
FaultCause   := ErrorIdCause AND (NOT WarningMask);  // bits fault (à acquitter)
WarningCause := ErrorIdCause AND WarningMask;          // bits warning (auto-effacés)
{endregion}

{region "§3 Défaut laté + acquittement"}
// 3. Front Reset : TOUJOURS effectif, jamais conditionné (std §9)
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    ErrorIdLatched := 0;
END_IF;
// 4. Ré-alarme : nouvelle apparition d'un fault non encore acquitté -> relatte
FaultEdge(CLK := (FaultCause <> 0));
IF FaultEdge.Q THEN
    ErrorIdLatched := ErrorIdLatched OR FaultCause;
END_IF;
// 5. Mémoire de l'état au défaut
IF (FaultCause <> 0) THEN
    Status.StateAtError := Status.State;
END_IF;
// 6. Sorties défaut : ErrorId = TOUS les bits (fault laté + warning auto-effacé).
//    WarningId reste le sous-ensemble warning (affichage IHM orange).
Status.ErrorId := ErrorIdLatched OR FaultCause OR WarningCause;
Status.Error := (Status.ErrorId <> 0);
Status.ResetRequested := (ErrorIdLatched <> 0);
{endregion}

{region "§4 Warning auto-effacé"}
Status.WarningId := WarningCause;
Status.Warning := (WarningCause <> 0);
{endregion}

{region "§5 Textes IHM"}
// 8. Sélection du texte : on affiche le texte du premier bit actif (le plus bas).
//    Parcours par boucle FOR + SHR (décalage) -> on lit le bit directement, aucun masque.
Status.ErrorIdTxt := '';
Status.WarningIdTxt := '';

// -- Texte ERROR : premier bit actif --
FOR i := 0 TO 15 DO
    IF (SHR(Status.ErrorId, i) AND 1) <> 0 THEN
        Status.ErrorIdTxt := ErrorTexts[i];
        EXIT;
    END_IF;
END_FOR;

// -- Texte WARNING : premier bit actif --
FOR i := 0 TO 15 DO
    IF (SHR(Status.WarningId, i) AND 1) <> 0 THEN
        Status.WarningIdTxt := WarningTexts[i];
        EXIT;
    END_IF;
END_FOR;
{endregion}

// Busy/Done : pilotés par le FB MÉTIER (cycle propre), pas par le socle.
// Le socle ne décide pas du cycle du FB métier — il gère Error/Warning/State/textes.
// Un conditionneur synchrone (ex. joystick) les laisse à FALSE ; un organe à cycle
// (treuil, séquenceur) les pilote lui-même après l'appel du socle.
